// Paste your source's Inbound URL and Signing secret. Replace the trigger above with any trigger; items with title/body fields are sent as they are.
const INBOUND_URL = 'https://YOUR-CAFE/api/inbound/HOUSE/SOURCE';
const SIGNING_SECRET = 'whsec_PASTE_YOUR_SIGNING_SECRET';

const crypto = require('crypto');
const key = Buffer.from(SIGNING_SECRET.replace(/^whsec_/, ''), 'base64');
const results = [];
for (const item of $input.all()) {
  const id = `n8n-${crypto.randomUUID()}`;
  const timestamp = String(Math.floor(Date.now() / 1000));
  const payload = JSON.stringify({ title: item.json.title || 'New event from n8n', body: item.json.body || JSON.stringify(item.json) });
  const signature = crypto.createHmac('sha256', key).update(`${id}.${timestamp}.${payload}`).digest('base64');
  const reply = await this.helpers.httpRequest({ method: 'POST', url: INBOUND_URL, body: payload, json: false, headers: { 'content-type': 'application/json', 'webhook-id': id, 'webhook-timestamp': timestamp, 'webhook-signature': `v1,${signature}` } });
  results.push({ json: { sent: id, reply } });
}
return results;
